		public void VoltarTelaHospedagem()
		{
			_seletorDireito.Get<PainelFichaHospedagem>().ProjetarHospedagem(Hospedagem);
			_seletorDireito.Selecionar<PainelFichaHospedagem>();
		}

		public void LerCartao()
		{
			try
			{
				ConfiguracaoDto configuracaoDto = DadosSistema.ConfiguracaoDto;
				RetornoLeituraCartao val = _leitorCartaoService.LerCartao(configuracaoDto.Geral.SenhaControleFechaduras.Valor);
				int year = HelperDate.ConvertToYYYY(HelperInteger.TryParseInteiro(HelperString.CopiarTexto(val.EndTime, 0, 2, true)));
				int month = HelperInteger.TryParseInteiro(HelperString.CopiarTexto(val.EndTime, 2, 2, true));
				int day = HelperInteger.TryParseInteiro(HelperString.CopiarTexto(val.EndTime, 4, 2, true));
				int hour = HelperInteger.TryParseInteiro(HelperString.CopiarTexto(val.EndTime, 6, 2, true));
				int minute = HelperInteger.TryParseInteiro(HelperString.CopiarTexto(val.EndTime, 8, 2, true));
				DataValidadeCartao = new DateTime(year, month, day, hour, minute, 0);
				NumeroQuarto = Hospedagem.Quarto.ToString();
				NumeroCartao = val.CardNo;
				NumeroInternoPorta = val.SuitDoor;
				NumeroPortaPublica = val.PubDoor;
				GuestSn = val.GuestSN;
				LeuCartao = true;
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
				VoltarTelaHospedagem();
			}
		}

