			{
				DialogoFactory.MostrarDialogoConfirma("O quarto ja possui uma reserva para o período.", false, System.Windows.HorizontalAlignment.Center);
				DataInicial = Hospedagem.DataInicialHospedagem;
				DataFinal = Hospedagem.DataFinalHospedagem;
