						return;
					}
					ClienteComandaDto dialogoComboBox = DialogoFactory.MostrarDialogoComboBox<ClienteComandaDto>("Informe qual pessoa será responsável pelo documento:", "Pessoas", hospedagemAtualizada.Hospedes?.Where((ClienteComandaDto x) => !HelperString.IsNullOrEmpty(x.PessoaDocumento)), "PessoaNome", true);
