					decimal num = ((DadosSistema.UtilizarPrePagoComoDescontoHospedagem && hospedagemAtualizada.TotalPrePagamento > 0m && hospedagemAtualizada.TotalPrePagamento < hospedagemAtualizada.TotalDiaria) ? hospedagemAtualizada.TotalPrePagamento : 0m);
