						hospedagemAtualizada.HistoricoHospedagem = val2.Itens;
						hospedagemAtualizada.ItensConsumidosNoQuarto = itensConsumidosQuarto.Select((ProdutosConsumidosQuartoViewModel x) => x.ProdutosConsumidosQuarto);
						_ = hospedagemAtualizada;
						hospedagemAtualizada = await DadosSistema.GetService().Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService service) => service.AtualizarHospedagem(hospedagemAtualizada)));
