				else if (DialogoFactory.MostrarDialogoSimNao("Essa hospedagem não gerou DAV-OS, deseja continuar?", false, 0, System.Windows.HorizontalAlignment.Center) == MessageBoxResult.Yes && DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<Hospedagem, PermitirRealizarCheckOutSemDav>(0m, (string)null) != null)
