					List<ItemDto> list = HelperIEnumerable.ToListEmptyWhenNull<ItemDto>(Itens.Where((ItemDto x) => x.Numero != itemDto.Numero));
					Itens.Clear();
					CollectionExtensions.AddRange<ItemDto>((Collection<ItemDto>)Itens, (IEnumerable<ItemDto>)HelperIEnumerable.ToListEmptyWhenNull<ItemDto>((IEnumerable<ItemDto>)list));
				}
				SalvarHospedagem();
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
			}
		}

		private void Gravar()
		{
			try
			{
				if (HelperObject.Is<PainelEsquerdoMapaQuartos>((object)_seletorEsquerdo.Painel))
				{
					_seletorEsquerdo.Get<PainelEsquerdoMapaQuartos>().Atualizar(Hospedagem);
					_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().PesquisarCommand.Execute(1);
				}
				else
				{
					_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AtualizarHospedagem(Hospedagem);
				}
			}
			catch (Exception value)
			{
				Console.WriteLine(value);
				throw;
			}
			finally
			{
				_seletorDireito.Voltar();
			}
		}

