		public string TituloPesquisa => "[Ctrl+F] Pesquisar";

		public string ToolTipPesquisa => "Aqui você pode pesquisar por:\nIdentificador da reserva ou nome do hóspede.";

		public ICommand AtualizarReservasCommand { get; protected set; }

		public ICommand PesquisarCommand { get; protected set; }

		public ICommand FecharCommand { get; protected set; }

		public PainelEsquerdoReservasHunit(IWService service, Seletor<IPainel> seletorDireito, Seletor<IPainel> seletorEsquerdo, IEventPublisher eventPublisher)
		{
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0045: Expected O, but got Unknown
			//IL_0052: Unknown result type (might be due to invalid IL or missing references)
			//IL_005c: Expected O, but got Unknown
			//IL_0069: Unknown result type (might be due to invalid IL or missing references)
			//IL_0073: Expected O, but got Unknown
			_service = service;
			_seletorDireito = seletorDireito;
			_seletorEsquerdo = seletorEsquerdo;
			Reservas = new Lista<ReservaHunitDto>();
			FecharCommand = (ICommand)new DelegateCommand((Action)FecharMethod);
			AtualizarReservasCommand = (ICommand)new AsyncCommand((Func<Task>)AtualizarReservasHunit);
			PesquisarCommand = (ICommand)new AsyncCommand((Func<Task>)Pesquisar);
			ObservableExtensions.Subscribe<MensagemResponse>(eventPublisher.GetEvent<MensagemResponse>(), (Action<MensagemResponse>)delegate(MensagemResponse response)
			{
				ThreadPrincipal.Executar((Action)async delegate
				{
					if ((int)response.Mensagem.TipoMensagemNotificacao == 5 && HelperObject.IsExactlyObject<PainelEsquerdoReservasHunit>((object)_seletorEsquerdo))
					{
						await AtualizarReservasHunit();
						if (!HelperString.IsNullOrEmpty(_idReservaPosicionada))
						{
							Reservas.Posicionar((Expression<Func<ReservaHunitDto, bool>>)((ReservaHunitDto x) => ((EntityBaseDto)x).Id.Equals(_idReservaPosicionada)));
						}
						((UpdateViewBindableBase)this).DormirAsync(100, (Action<object>)delegate
						{
							FocoNoListView = true;
						});
					}
				});
			});
		}

		public async Task Pesquisar()
		{
			try
			{
				await AtualizarReservasHunit();
			}
			catch (Exception)
			{
			}
			finally
			{
				TextoPesquisa = string.Empty;
				((UpdateViewBindableBase)this).RecuperarFoco();
			}
		}

		public async Task AtualizarReservasHunit()
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Processando...");
				PesquisaDto pesquisa = new PesquisaDto
				{
					Informacao = (InformacaoBaseDto)new TextoNumericoDto
					{
						Texto = HelperString.ToStringEmptyWhenNull(TextoPesquisa)
					},
					Pagina = Pagina,
					Tamanho = NumeroRegistrosPorPagina
				};
				IEnumerable<ReservaHunitDto> source = await _service.Canal<IHunitModuleService, Task<IEnumerable<ReservaHunitDto>>>((Func<IHunitModuleService, Task<IEnumerable<ReservaHunitDto>>>)((IHunitModuleService a) => a.ObterReservasPendentesHunit(pesquisa)));
				Reservas = new Lista<ReservaHunitDto>();
				Reservas.Adicionar((IEnumerable<ReservaHunitDto>)source.OrderByDescending((ReservaHunitDto x) => x.CreateDateTime));
				if (HelperObject.IsNotNull((object)_idReservaPosicionada))
				{
					Reservas?.Posicionar((Expression<Func<ReservaHunitDto, bool>>)((ReservaHunitDto x) => ((EntityBaseDto)x).Id.Equals(_idReservaPosicionada)));
					_seletorDireito.Get<PainelDireitoHunit>().Preencher(HelperObject.IsNull((object)Reservas.ItemSelecionado) ? null : Reservas?.ItemSelecionado);
				}
				else if (Reservas?.PossuiItemSelecionado ?? false)
				{
					Reservas?.PosicionarNoPrimeiro();
					_seletorDireito.Get<PainelDireitoHunit>().Preencher(Reservas.ItemSelecionado);
					_idReservaPosicionada = ((EntityBaseDto)Reservas.ItemSelecionado).Id;
				}
				Reservas.AlterouItemSelecionadoEvent += ReservasOnAlterouItemSelecionadoEvent;
				_reservas = new Lista<ReservaHunitDto>();
				_reservas.Adicionar((IEnumerable<ReservaHunitDto>)Reservas.Itens);
			}
			catch (Exception value)
			{
				Console.WriteLine(value);
				throw;
			}
			finally
			{
				((UpdateViewBindableBase)this).DormirAsync(100, (Action<object>)delegate
				{
					FocoNoListView = true;
				});
				_seletorDireito.Get<PainelDireitoHospedagem>().Preencher(null);
				ThreadPrincipal.Executar((Action)LoaderProcessoService.EsconderLoader);
			}
		}

		private void ReservasOnAlterouItemSelecionadoEvent(object sender, ReservaHunitDto reservation)
		{
			_seletorDireito.Selecionar<PainelDireitoHunit>();
			_seletorDireito.Get<PainelDireitoHunit>().Preencher(reservation);
			_idReservaPosicionada = ((EntityBaseDto)reservation).Id;
		}

