		private void EditarHospede(object comandasViewModel)
		{
			HospedesViewModel.Remover(comandasViewModel as HospedesViewModel);
			HospedesViewModel hospedesViewModel = comandasViewModel as HospedesViewModel;
			ClienteComandaDto cliente = hospedesViewModel.ClienteComanda;
			NomeHospede = cliente.PessoaNome;
			DocumentoHospede = cliente.PessoaDocumento;
			IEnumerable<string> telefone = cliente.Telefone;
			TelefoneHospede = ((telefone != null) ? HelperString.ToStringEmptyWhenNull(telefone.FirstOrDefault()) : null);
			ComandaHospede = cliente.Comanda;
			TipoPessoa = cliente.TipoPessoa;
			((Lista<Genero>)(object)Generos).Posicionar((Expression<Func<Genero, bool>>)((Genero x) => x.Codigo.Equals(cliente.Genero.Codigo)));
			((Lista<Raca>)(object)Racas).Posicionar((Expression<Func<Raca, bool>>)((Raca x) => x.Codigo.Equals(cliente.Raca.Codigo)));
			((Lista<Deficiencia>)(object)Deficiencias).Posicionar((Expression<Func<Deficiencia, bool>>)((Deficiencia x) => x.Codigo.Equals(cliente.Deficiencia.Codigo)));
			((Lista<OpcoesDeficiencia>)(object)OpcoesDeficiencias).Posicionar((Expression<Func<OpcoesDeficiencia, bool>>)((OpcoesDeficiencia x) => x.Codigo.Equals(cliente.OpcaoDeficiencia.Codigo)));
			Nacionalidade = cliente.Nacionalidade;
			Estrangeiro = cliente.TipoPessoa.Equals("Estrangeira");
		}

