		public async Task Gravar()
		{
			try
			{
				Gravando = true;
				if (QuartosLivres.Count((QuartoDisponivel x) => x.IsSelecionado) > 1)
				{
					string arg = string.Join("\n", from q in QuartosLivres
						where q.IsSelecionado
						select q.Key);
					if (DialogoFactory.MostrarDialogoSimNao($"Deseja hospedar nos seguintes quartos:\n{arg}?", false, 0, System.Windows.HorizontalAlignment.Center) != MessageBoxResult.Yes)
					{
						return;
					}
				}
				List<HospedagemDto> hospedagensCriadas = new List<HospedagemDto>();
				foreach (QuartoDisponivel quarto in QuartosLivres.Where((QuartoDisponivel x) => x.IsSelecionado))
				{
					SituacaoHospedagemDto val = new SituacaoHospedagemDto
					{
						Codigo = SituacoesQuartos.ObterPorCodigo(2).Codigo,
						Descricao = SituacoesQuartos.ObterPorCodigo(2).Descricao,
						Cor = SituacoesQuartos.ObterPorCodigo(2).Cor
					};
					if (HelperObject.Is<HospedagemDtoNull>((object)HospedagemDto))
					{
						HospedagemDto = new HospedagemDto();
					}
					HospedagemDto.Hospedes = HospedesViewModel.Itens.Select((HospedesViewModel x) => x.ClienteComanda);
					HospedagemDto.Quarto = quarto.Value;
					AgrupamentoQuartoDto result = _service.Canal<IAgrupamentoQuartoModuleService, Task<AgrupamentoQuartoDto>>((Func<IAgrupamentoQuartoModuleService, Task<AgrupamentoQuartoDto>>)((IAgrupamentoQuartoModuleService x) => x.ObterAgrupamentoQuartoEspecifico(quarto.Value))).Result;
					HospedagemDto.AgrupamentoReferencia = ((EntityBaseDto)result).Id;
					HospedagemDto.ValoresDiaria = DiariasViewModel.Itens.Select((PeriodoPrecoHospedagemViewModel x) => x.PeriodoPreco);
					HospedagemDto.Observacao = Observacao;
					HospedagemDto.PrevisaoCheckIn = PrevisaoCheckIn;
					HospedagemDto.PrevisaoCheckOut = PrevisaoCheckOut;
					HospedagemDto.SituacaoHospedagem = val;
					HospedagemDto.TotalPrePagamento = TotalPrePagamento;
					HospedagemDto.Cafe = Cafe;
					HospedagemDto.Almoco = Almoco;
					HospedagemDto.Janta = Janta;
					HospedagemDto.Usuario = DadosSistema.NomeUsuario;
					HospedagemDto.Servico = Servico;
					HospedagemDto.QuantidadeHospedes = QuantidadeHospedes;
					HospedagemDto.SituacaoHospedagem = new SituacaoHospedagemDto
					{
						Codigo = SituacaoHospedagem.ItemSelecionado.Codigo,
						Descricao = SituacaoHospedagem.ItemSelecionado.Descricao,
						Cor = SituacaoHospedagem.ItemSelecionado.Cor
					};
					HospedagemDto.MotivoViagem = MotivosViagem.Dto();
					HospedagemDto.MeioTransporte = MeiosTransporte.Dto();
					Lista<HistoricoHospedagemDto> val2 = new Lista<HistoricoHospedagemDto>();
					val2.Adicionar(HospedagemDto.HistoricoHospedagem);
					val2.Adicionar(new HistoricoHospedagemDto
					{
						DataHora = DateTime.Now,
						Usuario = $"{DadosSistema.NomeUsuario}",
						Titulo = (((EntityBaseDto)HospedagemDto).IsTransient() ? "Incluído" : "Editado"),
						SituacaoAntiga = _situacaoHospedagem,
						NovaSituacaoQuarto = new SituacaoHospedagemDto
						{
							Codigo = val.Codigo,
							Descricao = val.Descricao,
							Cor = val.Cor
						},
						IsCheckOut = false
					});
					HospedagemDto.HistoricoHospedagem = val2.Itens;
					if (((EntityBaseDto)HospedagemDto).IsTransient())
					{
						hospedagensCriadas.Add(await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService service) => service.AdicionarHospedagem(HospedagemDto))));
					}
				}
				if (((EntityBaseDto)HospedagemDto).IsTransient())
				{
					AtualizarPainelEsquerdo(hospedagensCriadas);
				}
				else if (HelperObject.Is<PainelEsquerdoMapaQuartos>((object)_seletorEsquerdo.Painel))
				{
					PainelEsquerdoMapaQuartos painelEsquerdoMapaQuartos = _seletorEsquerdo.Get<PainelEsquerdoMapaQuartos>();
					painelEsquerdoMapaQuartos.Atualizar(await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService service) => service.AtualizarHospedagem(HospedagemDto))));
				}
				else
				{
					PainelEsquerdoListaQuartos painelEsquerdoListaQuartos = _seletorEsquerdo.Get<PainelEsquerdoListaQuartos>();
					painelEsquerdoListaQuartos.AtualizarHospedagem(await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService service) => service.AtualizarHospedagem(HospedagemDto))));
				}
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
				throw;
			}
			finally
			{
				Gravando = false;
			}
			_seletorDireito.Voltar();
		}

		public void AtualizarPainelEsquerdo(IEnumerable<HospedagemDto> hospedagens)
		{
			foreach (HospedagemDto hospedagen in hospedagens)
			{
				if (HelperObject.Is<PainelEsquerdoMapaQuartos>((object)_seletorEsquerdo.Painel))
				{
					_seletorEsquerdo.Get<PainelEsquerdoMapaQuartos>().Atualizar(hospedagen);
				}
				else
				{
					_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().PesquisarCommand.Execute(1);
				}
			}
		}

