		public DateTime RetornarDataCheckOut(HospedagemDto hospedagemDto)
		{
			int year = DateTime.Now.Year;
			int month = DateTime.Now.Month;
			int day = DateTime.Now.Day;
			int hour = DateTime.Now.Hour;
			bool flag = DateTime.DaysInMonth(year, month).Equals(day);
			if (!hospedagemDto.DataPrevisaoCheckOut.Equals(DateTime.MinValue))
			{
				return hospedagemDto.DataPrevisaoCheckOut;
			}
			if (!DadosSistema.ConfiguracaoDto.Geral.CalcularPrecoPorHoraHospedagem.Valor)
			{
				return new DateTime((flag && month == 12) ? (year + 1) : year, (!flag) ? month : ((month == 12) ? 1 : (month + 1)), flag ? 1 : (day + 1), DadosSistema.HorarioPadraoCheckOut.Hour, DadosSistema.HorarioPadraoCheckOut.Minute, 0);
			}
			return new DateTime((flag && month == 12) ? (year + 1) : year, (!flag || !hour.Equals(23)) ? month : ((month == 12) ? 1 : (month + 1)), (flag && hour.Equals(23)) ? 1 : day, (hour + 1 < 24) ? (hour + 1) : 0, DateTime.Now.Minute, 0);
		}

		public bool PodeVerificarDisponibilidadeQuartos()
		{
			if (PrevisaoCheckIn <= PrevisaoCheckOut)
			{
				return QuantidadeHospedes > 0;
			}
			return false;
		}

		public static bool VerificarPeriodos(DateTime dataInicialCadastrada, DateTime dataFinalCadastrada, DateTime dataInicialNova, DateTime dataFinalNova)
		{
			if ((!(dataInicialCadastrada < dataInicialNova) || !(dataInicialNova < dataFinalCadastrada)) && (!(dataInicialCadastrada < dataFinalNova) || !(dataFinalNova <= dataFinalCadastrada)) && (!(dataInicialNova < dataInicialCadastrada) || !(dataFinalNova > dataFinalCadastrada)))
			{
				if (dataInicialCadastrada < dataFinalNova)
				{
