		public async Task VerificarDisponibilidadeQuartos()
		{
			_ = 1;
			try
			{
				LoaderProcessoService.MostrarLoader("Verificando disponibilidades...");
				if (!((EntityBaseDto)HospedagemDto).IsTransient())
				{
					if ((await _service.Canal<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>((Func<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>)((IHospedagemModuleService x) => x.ObterReservasPorNumeroQuarto(QuartosLivres.First().Value)))).Where((HospedagemDto x) => ((EntityBaseDto)x).Id != ((EntityBaseDto)HospedagemDto).Id).Any((HospedagemDto x) => VerificarPeriodos(x.DataPrevisaoCheckIn, x.DataPrevisaoCheckOut, PrevisaoCheckIn, PrevisaoCheckOut)))
					{
						DialogoFactory.MostrarDialogoConfirma("O quarto ja possui uma reserva para o período.", false, System.Windows.HorizontalAlignment.Center);
						PrevisaoCheckIn = HospedagemDto.PrevisaoCheckIn;
						PrevisaoCheckOut = HospedagemDto.PrevisaoCheckOut;
					}
					return;
				}
				IEnumerable<HospedagemDto> source = await _service.Canal<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>((Func<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>)((IHospedagemModuleService x) => x.ObterHospedagensParaAdicionarReserva(PrevisaoCheckIn, PrevisaoCheckOut, 99)));
				IEnumerable<int> enumerable = _seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.Where((AgrupamentoQuartoDto x) => x.PeriodosPrecos.Any((PeriodoPrecoQuartoDto y) => y.PrecoPorQuantidadeHospede.Select((PrecoPorQuantidadeHospedeDto j) => j.QuantidadeHospede).Contains(QuantidadeHospedes))).SelectMany((AgrupamentoQuartoDto t) => t.QuartosVinculados).Concat(_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.Where((AgrupamentoQuartoDto x) => HelperObject.IsNull((object)x.PeriodosPrecos) || HelperObject.Is<PeriodoPrecoHospedagemDtoNull>((object)x.PeriodosPrecos) || !x.PeriodosPrecos.Any()).SelectMany((AgrupamentoQuartoDto k) => k.QuartosVinculados))
					.Except(source.Select((HospedagemDto x) => x.Quarto));
				if (!enumerable.Any())
				{
					DialogoFactory.MostrarDialogoConfirma("Não existem quartos disponíveis para o período!", false, System.Windows.HorizontalAlignment.Center);
					DiariasViewModel?.Limpar();
					QuartosLivres?.Clear();
					return;
				}
				QuartosLivres = new ObservableCollection<QuartoDisponivel>();
				foreach (int quartoLivreViewModel in enumerable)
				{
					AgrupamentoQuartoDto val = _seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto x) => x.QuartosVinculados.Contains(quartoLivreViewModel));
					QuartoDisponivel quartoDisponivel = new QuartoDisponivel($"{quartoLivreViewModel} {val.Descricao}", quartoLivreViewModel, selecionado: false);
					((BindableBase)quartoDisponivel).PropertyChanged += ItemPropertyChanged;
					QuartosLivres.Add(quartoDisponivel);
				}
				if (PrevisaoCheckIn > DateTime.Now)
				{
					SituacaoHospedagem.Posicionar((Expression<Func<SituacaoQuarto, bool>>)((SituacaoQuarto x) => x.Codigo.Equals(2)));
				}
				FocoQuantidadeHospede = false;
			}
			catch (Exception value)
			{
				Console.WriteLine(value);
				throw;
			}
			finally
			{
				List<PeriodoPrecoHospedagemViewModel> diariasSalvas = (((EntityBaseDto)HospedagemDto).IsTransient() ? new List<PeriodoPrecoHospedagemViewModel>() : DiariasViewModel.Itens.ToList());
				DiariasViewModel.Limpar();
				LinqExtensions.ForEach<QuartoDisponivel>((IEnumerable<QuartoDisponivel>)QuartosLivres, (Action<QuartoDisponivel>)delegate(QuartoDisponivel x)
				{
					((BindableBase)x).PropertyChanged += ItemPropertyChanged;
				});
				QuartosLivres?.FirstOrDefault()?.SetarSelecionado(selecionado: true);
				if (QuartosLivres.Count.Equals(1))
				{
					AlterouQuartoSelecionado();
				}
				PreencherPrecos();
				ManterDiariasSalvas(diariasSalvas);
				ExibirSelecionarQuartoPreco = true;
				FocoNumeroQuarto = true;
				ThreadPrincipal.Executar((Action)LoaderProcessoService.EsconderLoader);
			}
		}

