		private void AtualizarTextoSelecionado()
		{
			List<QuartoDisponivel> list = QuartosLivres.Where((QuartoDisponivel x) => x.IsSelecionado).ToList();
			if (list.Count > 1)
			{
				TextoItemSelecionado = $"SELECIONADOS: {list.Count}";
			}
			else if (list.Count == 1)
