			}
			return true;
		}

		private async Task TransferirQuarto(object obj)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Processando...");
				PodeFechar = false;
				if (HelperObject.IsNull(obj))
				{
					return;
				}
				AppointmentDragEventArgs itemSelecionado = (AppointmentDragEventArgs)((obj is AppointmentDragEventArgs) ? obj : null);
				QuartoViewModel quartoViewModel = Quartos.Itens.FirstOrDefault((QuartoViewModel x) => x.Id.Equals(((IPersistentObject)itemSelecionado.SourceAppointment).Id));
				bool quartoOcupado = HelperObject.Is<QuartoOcupadoViewModel>((object)quartoViewModel);
				HospedagemDto hospedagemAtualizada = default(HospedagemDto);
				_ = hospedagemAtualizada;
				hospedagemAtualizada = await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService x) => x.ObterHospedagemReferencia(((EntityBaseDto)quartoViewModel.Hospedagem).Id)));
				int quartoHospedagemOrigem = 0;
				if (quartoOcupado)
				{
					quartoHospedagemOrigem = hospedagemAtualizada.Quarto;
				}
				Lista<HistoricoHospedagemDto> historicos = new Lista<HistoricoHospedagemDto>();
				historicos.Adicionar(hospedagemAtualizada.HistoricoHospedagem);
				historicos.Adicionar(new HistoricoHospedagemDto
				{
					DataHora = DateTime.Now,
					Usuario = $"{DadosSistema.NomeUsuario}",
					Titulo = "Transferência de quarto",
					NovaSituacaoQuarto = new SituacaoHospedagemDto
					{
						Codigo = hospedagemAtualizada.SituacaoHospedagem.Codigo,
						Descricao = hospedagemAtualizada.SituacaoHospedagem.Descricao,
						Cor = hospedagemAtualizada.SituacaoHospedagem.Cor
					},
					Observacao = $"Transferido do quarto {hospedagemAtualizada.Quarto} para o quarto {HelperObject.ToInt(((IPersistentObject)itemSelecionado.HitResource).Id)}.",
					SituacaoAntiga = hospedagemAtualizada.SituacaoHospedagem.Descricao,
					IsCheckOut = false
				});
				List<ItemMesaContaDto> itensQuartoNovo = new List<ItemMesaContaDto>();
				if (quartoOcupado && hospedagemAtualizada.Itens.Any())
				{
					foreach (ItemMesaContaDto itemMesaContaDto in hospedagemAtualizada.Itens)
					{
						itensQuartoNovo.Add((await _service.Canal<IRestauranteModuleService, Task<IEnumerable<ItemMesaContaDto>>>((Func<IRestauranteModuleService, Task<IEnumerable<ItemMesaContaDto>>>)((IRestauranteModuleService y) => y.TransferirItensMesaConta((IEnumerable<ItemMesaContaDto>)(object)new ItemMesaContaDto[1] { itemMesaContaDto }, itemMesaContaDto.NumeroMesaConta, false, HelperObject.ToInt(((IPersistentObject)itemSelecionado.HitResource).Id))))).FirstOrDefault());
					}
				}
				hospedagemAtualizada.Itens = new List<ItemMesaContaDto>();
				hospedagemAtualizada.Itens = itensQuartoNovo;
				hospedagemAtualizada.Quarto = HelperObject.ToInt(((IPersistentObject)itemSelecionado.HitResource).Id);
				hospedagemAtualizada.HistoricoHospedagem = historicos.Itens;
				hospedagemAtualizada.AgrupamentoReferencia = ((EntityBaseDto)_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto x) => x.QuartosVinculados.Contains(HelperObject.ToInt(((IPersistentObject)itemSelecionado.HitResource).Id)))).Id;
				if (quartoViewModel.Hospedagem.IsReservadoPreReservado)
				{
					hospedagemAtualizada.PrevisaoCheckIn = itemSelecionado.SourceAppointment.Start;
					hospedagemAtualizada.PrevisaoCheckOut = itemSelecionado.SourceAppointment.End;
				}
				else
				{
					hospedagemAtualizada.DataInicialHospedagem = itemSelecionado.SourceAppointment.Start;
					hospedagemAtualizada.DataFinalHospedagem = itemSelecionado.SourceAppointment.End;
				}
				hospedagemAtualizada.ValoresDiaria = PreencherPreco(hospedagemAtualizada, DadosSistema.ConfiguracaoDto.Geral.CalcularPrecoPorHoraHospedagem.Valor);
				if (itemSelecionado.SourceAppointment.Start.Equals(DateTime.MinValue) || itemSelecionado.SourceAppointment.End.Equals(DateTime.MinValue))
				{
					DialogoFactory.MostrarDialogoConfirma("Não foi possível transferir. Por favor, tente novamente.", false, System.Windows.HorizontalAlignment.Center);
					return;
				}
				HospedagemDto val = await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService x) => x.AtualizarHospedagem(hospedagemAtualizada)));
				QuartoViewModel quarto = new QuartoViewModel(val.Quarto, quartoViewModel.DescricaoAgrupamento, val);
				quartoViewModel.Hospedagem = val;
				_seletorDireito.Get<PainelDireitoHospedagem>().Preencher(quarto);
				if (quartoHospedagemOrigem > 0)
				{
					Lista<KeyValuePair<int, string>> val2 = new Lista<KeyValuePair<int, string>>();
					val2.Adicionar(new KeyValuePair<int, string>(1, "Livre"));
					val2.Adicionar(new KeyValuePair<int, string>(2, "Aguardando limpeza"));
					val2.Adicionar(new KeyValuePair<int, string>(3, "Aguardando manutenção"));
					switch (DialogoFactory.MostrarDialogoComboBox<KeyValuePair<int, string>>("Informe a situação desejada para o quarto anteriormente ocupado", "Situações disponíveis", (IEnumerable<KeyValuePair<int, string>>)val2.Itens, "Value", true).Key)
					{
					case 2:
						await SetarQuartoAguardandoLimpeza(quartoHospedagemOrigem);
						break;
					case 3:
						_seletorDireito.Get<PainelDireitoManutencao>().Preencher(quartoHospedagemOrigem);
						_seletorDireito.Selecionar<PainelDireitoManutencao>();
						break;
					}
				}
			}
			catch (Exception value)
			{
				Console.WriteLine(value);
				throw;
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
				PodeFechar = true;
			}
		}

		public IEnumerable<PeriodoPrecoHospedagemDto> PreencherPreco(HospedagemDto hospedagem, bool horas)
		{
			//IL_017f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0184: Unknown result type (might be due to invalid IL or missing references)
			//IL_0191: Unknown result type (might be due to invalid IL or missing references)
			//IL_00c9: Unknown result type (might be due to invalid IL or missing references)
			//IL_00ce: Unknown result type (might be due to invalid IL or missing references)
			//IL_00db: Unknown result type (might be due to invalid IL or missing references)
			List<PeriodoPrecoHospedagemDto> list = new List<PeriodoPrecoHospedagemDto>();
			List<PeriodoPrecoHospedagemDto> list2 = HelperIEnumerable.ToListEmptyWhenNull<PeriodoPrecoHospedagemDto>(hospedagem.ValoresDiaria);
			DateTime dateTime = (hospedagem.IsReservadoPreReservado ? hospedagem.PrevisaoCheckIn : hospedagem.DataInicialHospedagem);
			DateTime dateTime2 = (hospedagem.IsReservadoPreReservado ? hospedagem.PrevisaoCheckOut : hospedagem.DataFinalHospedagem);
			decimal valor = ObterValorNovaDiaria(list2, hospedagem, dateTime, dateTime2);
			if (horas)
			{
				int num = HelperDate.QuantasHorasEntreDatasArredondado(dateTime, dateTime2);
				int num2 = (num.Equals(0) ? 1 : num);
				for (int i = 0; i < num2; i++)
				{
					DateTime dataAtual2 = (hospedagem.IsReservadoPreReservado ? hospedagem.PrevisaoCheckIn.AddHours(i) : hospedagem.DataInicialHospedagem.AddHours(i));
					PeriodoPrecoHospedagemDto val = list2.FirstOrDefault((PeriodoPrecoHospedagemDto x) => MesmaDataDiaria(x, dataAtual2, horas: true));
					list.Add((PeriodoPrecoHospedagemDto)(((object)val) ?? ((object)new PeriodoPrecoHospedagemDto
					{
						Data = dataAtual2,
						Valor = valor
					})));
				}
			}
			else
			{
				int num3 = HelperDate.QuantosDiasEntreDatas(dateTime2.Date, dateTime.Date);
				int num4 = (num3.Equals(0) ? 1 : num3);
				for (int j = 0; j < num4; j++)
				{
					DateTime dataAtual = (hospedagem.IsReservadoPreReservado ? hospedagem.PrevisaoCheckIn.AddDays(j) : hospedagem.DataInicialHospedagem.AddDays(j));
					PeriodoPrecoHospedagemDto val2 = list2.FirstOrDefault((PeriodoPrecoHospedagemDto x) => MesmaDataDiaria(x, dataAtual, horas: false));
					list.Add((PeriodoPrecoHospedagemDto)(((object)val2) ?? ((object)new PeriodoPrecoHospedagemDto
					{
						Data = dataAtual,
						Valor = valor
					})));
				}
			}
			return list;
		}

		private static bool MesmaDataDiaria(PeriodoPrecoHospedagemDto diariaSalva, DateTime dataAtual, bool horas)
		{
			if (!diariaSalva.Data.Date.Equals(dataAtual.Date))
			{
				return false;
			}
			if (horas)
			{
				return diariaSalva.Data.Hour.Equals(dataAtual.Hour);
			}
			return true;
		}

		private decimal ObterValorNovaDiaria(List<PeriodoPrecoHospedagemDto> diariasSalvas, HospedagemDto hospedagem, DateTime dataInicial, DateTime dataFinal)
		{
			PeriodoPrecoHospedagemDto obj = diariasSalvas.LastOrDefault();
			decimal result = ((obj != null) ? obj.Valor : 0m);
			PeriodoPrecoQuartoDto val = ObterPeriodoPrecoQuarto(hospedagem.Quarto, dataInicial, dataFinal);
			if ((!((val == null) ? null : val.PrecoPorQuantidadeHospede?.Any())) ?? true)
			{
				return result;
			}
			if (hospedagem.QuantidadeHospedes <= 0)
			{
				PrecoPorQuantidadeHospedeDto obj2 = val.PrecoPorQuantidadeHospede.FirstOrDefault();
				if (obj2 == null)
				{
					return result;
				}
				return obj2.PrecoPeriodo;
			}
			if (!val.PrecoPorQuantidadeHospede.Select((PrecoPorQuantidadeHospedeDto x) => x.QuantidadeHospede).Contains(hospedagem.QuantidadeHospedes))
			{
				PrecoPorQuantidadeHospedeDto obj3 = val.PrecoPorQuantidadeHospede.LastOrDefault();
				if (obj3 == null)
				{
					return result;
				}
				return obj3.PrecoPeriodo;
			}
			PrecoPorQuantidadeHospedeDto obj4 = val.PrecoPorQuantidadeHospede.FirstOrDefault((PrecoPorQuantidadeHospedeDto x) => x.QuantidadeHospede.Equals(hospedagem.QuantidadeHospedes));
			if (obj4 == null)
			{
				return result;
			}
			return obj4.PrecoPeriodo;
		}

		private PeriodoPrecoQuartoDto ObterPeriodoPrecoQuarto(int quarto, DateTime dataInicial, DateTime dataFinal)
