		public void ProjetarQuartos(IEnumerable<QuartoViewModel> quartos, IEnumerable<AgrupamentoQuartoDto> grupoQuartos)
		{
			_quartos.Limpar();
			_quartos.Adicionar(quartos);
			Quartos = new Lista<QuartoViewModel>();
			Quartos.Adicionar(quartos);
			QuartosAgrupados = new Lista<QuartosAgrupadosViewModel>();
			foreach (IGrouping<int, QuartoViewModel> agrupado in from x in (from x in quartos
					group x by HelperObject.ToInt((object)x.Numero)).ToList()
				orderby x.Key
				select x)
			{
				QuartosAgrupados.Adicionar(QuartosAgrupadosViewModel.Criar().ComNumeroQuarto(agrupado.Key).ComDescricaoQuarto($"Quarto {agrupado.Key}\n" + $"({quartos.FirstOrDefault((QuartoViewModel y) => y.Numero.Equals(agrupado.Key)).DescricaoAgrupamento})"));
			}
			_quartosAgrupados.Limpar();
			_quartosAgrupados.Adicionar((IEnumerable<QuartosAgrupadosViewModel>)QuartosAgrupados.Itens);
			AgrupamentosQuartos = new Lista<AgrupamentoQuartoDto>();
			AgrupamentosQuartos.Adicionar(grupoQuartos);
			AgrupamentosQuartos.PosicionarNoUltimo();
			AgrupamentosQuartos.AlterouItemSelecionadoEvent += AgrupamentosQuartosOnAlterouItemSelecionadoEvent;
		}

		private void AgrupamentosQuartosOnAlterouItemSelecionadoEvent(object sender, AgrupamentoQuartoDto agrupamentoQuartoDto)
		{
			if (((agrupamentoQuartoDto != null) ? ((EntityBaseDto)agrupamentoQuartoDto).Id : null) != "Todos")
			{
				QuartosAgrupados.Limpar();
				{
					foreach (int grupo in agrupamentoQuartoDto.QuartosVinculados)
					{
						QuartosAgrupados.Adicionar(_quartosAgrupados.Itens.Where((QuartosAgrupadosViewModel x) => x.Numero.Equals(grupo)));
					}
					return;
				}
			}
			QuartosAgrupados.Limpar();
			QuartosAgrupados.Adicionar((IEnumerable<QuartosAgrupadosViewModel>)_quartosAgrupados.Itens);
		}

