		private async Task ImprimirDemonstrativoConsumo()
		{
			try
			{
				HospedagemDto val = await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService x) => x.ObterHospedagemReferencia(((EntityBaseDto)Hospedagem).Id)));
