				{
					LoaderProcessoService.MostrarLoader("Imprimindo demonstrativo consumo...");
					if (DadosSistema.ConfiguracaoDto.Geral.UsarImpresso40ColunasHospedagens.Valor)
					{
						XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new DemonstrativoConsumoSemCliente40Colunas(val)).Processar());
					}
					else
					{
						XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new DemonstrativoConsumoSemCliente(val)).Processar());
					}
					return;
				}
				ClienteComandaDto val2 = DialogoFactory.MostrarDialogoComboBox<ClienteComandaDto>("Informe de qual comanda você deseja obter o demonstrativo de consumo", "Comandas", val.Hospedes, "Comanda", true);
				if (!HelperObject.IsNull((object)val2))
				{
					PessoaDto val3 = ObterPessoa(val2.PessoaReferencia);
					PessoaDto pessoa = (PessoaDto)((!HelperObject.Is<PessoaDtoNull>((object)val3)) ? ((object)val3) : ((object)new PessoaDto
					{
						Nome = val2.PessoaNome,
						CpfCnpjFormatado = val2.PessoaDocumento
					}));
					LoaderProcessoService.MostrarLoader("Imprimindo demonstrativo consumo...");
					if (DadosSistema.ConfiguracaoDto.Geral.UsarImpresso40ColunasHospedagens.Valor)
					{
						XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new DemonstrativoConsumo40Colunas(val, pessoa, val2.Comanda)).Processar());
					}
					else
					{
						XtraReportExtensions.ShowPreviewDialog((IReport)(object)((Relatorio)new DemonstrativoConsumo(val, pessoa, val2.Comanda)).Processar());
					}
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message, false, System.Windows.HorizontalAlignment.Center);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

