		}

		private static string ObterTelefonePreferido(PessoaDto pessoa)
		{
			TelefoneDto telefoneWhatsApp = pessoa.TelefoneWhatsApp;
			if (telefoneWhatsApp != null && !HelperString.IsNullOrEmpty(telefoneWhatsApp.Numero))
			{
				return pessoa.TelefoneWhatsApp.Numero;
			}
			TelefoneDto val = pessoa.Celulares?.FirstOrDefault((TelefoneDto x) => !HelperString.IsNullOrEmpty(x.Numero));
			if (val == null)
			{
				TelefoneDto telefonePrincipal = pessoa.TelefonePrincipal;
				if (telefonePrincipal == null)
				{
					return null;
				}
				return HelperString.ToStringEmptyWhenNull(telefonePrincipal.Numero);
			}
			return val.Numero;
		}

		private void CallbackPessoa(PessoaDto pessoa)
		{
			//IL_0402: Unknown result type (might be due to invalid IL or missing references)
			//IL_040c: Expected O, but got Unknown
			Cliente = pessoa;
			NomeHospede = ((BaseDto)pessoa).ToText;
			TelefoneHospede = ObterTelefonePreferido(pessoa);
			object documentoHospede;
			if (!pessoa.TipoCadastroToText.Equals("Estrangeira"))
			{
				documentoHospede = pessoa.CpfCnpjFormatado;
			}
			else
			{
				EstrangeiroDto estrangeiro = pessoa.Estrangeiro;
				documentoHospede = ((estrangeiro != null) ? HelperString.ToStringEmptyWhenNull(estrangeiro.IdEstrangeiro) : null);
			}
			DocumentoHospede = (string)documentoHospede;
			Mascara = (pessoa.TipoCadastroToText.Equals("Jurídica") ? "AA.AAA.AAA/AAAA-AA" : (pessoa.TipoCadastroToText.Equals("Física") ? "000.000.000-00" : string.Empty));
			TipoPessoa = pessoa.TipoCadastroToText;
			((Lista<Genero>)(object)Generos).Posicionar((Expression<Func<Genero, bool>>)((Genero x) => x.Codigo.Equals(pessoa.Fisica.Genero.Codigo)));
			((Lista<Raca>)(object)Racas).Posicionar((Expression<Func<Raca, bool>>)((Raca x) => x.Codigo.Equals(pessoa.Fisica.Raca.Codigo)));
			((Lista<Deficiencia>)(object)Deficiencias).Posicionar((Expression<Func<Deficiencia, bool>>)((Deficiencia x) => x.Codigo.Equals(pessoa.Fisica.Deficiencia.Codigo)));
			((Lista<OpcoesDeficiencia>)(object)OpcoesDeficiencias).Posicionar((Expression<Func<OpcoesDeficiencia, bool>>)((OpcoesDeficiencia x) => x.Codigo.Equals(pessoa.Fisica.OpcaoDeficiencia.Codigo)));
			Nacionalidade = (HelperObject.Is<PaisDtoNull>((object)pessoa.Fisica.Nacionalidade) ? PaisProjection.ProjectedAsDto(new Pais(1058, "Brasil", "BR")) : pessoa.Fisica.Nacionalidade);
			if (pessoa.TipoCadastroToText.Equals("Estrangeira"))
			{
				Nacionalidade = pessoa.EnderecoPrincipal.Pais;
			}
			Estrangeiro = pessoa.TipoCadastroToText.Equals("Estrangeira");
		}

		public void SetarInformacoesReserva(HospedagemDto hospedagem)
		{
			PrevisaoCheckIn = hospedagem.PrevisaoCheckIn;
			PrevisaoCheckOut = hospedagem.PrevisaoCheckOut;
			DataInicialHospedagem = hospedagem.PrevisaoCheckIn;
			DataFinalHospedagem = hospedagem.PrevisaoCheckOut;
			if (!HelperIEnumerable.IsEmpty<char>((IEnumerable<char>)DadosSistema.ConfiguracaoDto.Geral.ServicoPadraoHospedagem.Referencia))
			{
				IEnumerable<ProdutoServicoEmpresaDto> source = _service.Canal<IProdutoServicoModuleService, IEnumerable<ProdutoServicoEmpresaDto>>((Func<IProdutoServicoModuleService, IEnumerable<ProdutoServicoEmpresaDto>>)((IProdutoServicoModuleService service) => service.ObterProdutoServicoEmpresaPorId(new string[1] { DadosSistema.ConfiguracaoDto.Geral.ServicoPadraoHospedagem.Referencia })));
				Servico = source.FirstOrDefault();
				FocoPessoa = true;
				InformacaoPesquisa = ((BaseDto)Servico).ToText ?? string.Empty;
			}
			QuartosLivres = new ObservableCollection<QuartoDisponivel>();
			AgrupamentoQuartoDto val = _seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto x) => x.QuartosVinculados.Contains(hospedagem.Quarto));
			QuartosLivres.Add(new QuartoDisponivel($"{HelperObject.ToInt((object)hospedagem.Quarto)} {val.Descricao}", hospedagem.Quarto, selecionado: true));
			ExibirSelecionarQuartoPreco = true;
			SituacaoHospedagem.Posicionar((Expression<Func<SituacaoQuarto, bool>>)((SituacaoQuarto x) => x.Codigo.Equals(3)));
		}

