					}
				}
				if (HelperObject.IsNot<ProdutoServicoEmpresaDtoNull>((object)Servico) && ExibirSelecionarQuartoPreco)
				{
					goto IL_00f5;
				}
			}
			goto IL_0088;
			IL_0088:
			if (!SituacaoHospedagem.ItemSelecionado.Codigo.Equals(8) && !SituacaoHospedagem.ItemSelecionado.Codigo.Equals(4) && !SituacaoHospedagem.ItemSelecionado.Codigo.Equals(9))
			{
				return SituacaoHospedagem.ItemSelecionado.Codigo.Equals(9);
