				HospedagemDto.Observacao = Observacao;
				HospedagemDto.PlacaVeiculo = PlacaVeiculo;
				HospedagemDto.DataInicialHospedagem = DataInicialHospedagem;
				HospedagemDto.DataFinalHospedagem = DataFinalHospedagem;
