		private void ManterDiariasSalvas(IList<PeriodoPrecoHospedagemViewModel> diariasSalvas)
		{
			if (!diariasSalvas.Any())
			{
				return;
			}
			List<PeriodoPrecoHospedagemViewModel> list = DiariasViewModel.Itens.Select((PeriodoPrecoHospedagemViewModel diaria) => diariasSalvas.FirstOrDefault((PeriodoPrecoHospedagemViewModel salva) => MesmaDataDiaria(salva, diaria)) ?? diaria).ToList();
			DiariasViewModel.Limpar();
			DiariasViewModel.Adicionar((IEnumerable<PeriodoPrecoHospedagemViewModel>)list);
		}

		private bool MesmaDataDiaria(PeriodoPrecoHospedagemViewModel diariaSalva, PeriodoPrecoHospedagemViewModel diariaNova)
		{
			if (!diariaSalva.PeriodoPreco.Data.Date.Equals(diariaNova.PeriodoPreco.Data.Date))
			{
				return false;
			}
			if (DadosSistema.ConfiguracaoDto.Geral.CalcularPrecoPorHoraHospedagem.Valor)
			{
				return diariaSalva.PeriodoPreco.Data.Hour.Equals(diariaNova.PeriodoPreco.Data.Hour);
			}
			return true;
		}

