		private async Task AdicionarServicos()
		{
			HospedagemDto val = await DadosSistema.GetService().Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService service) => service.AtualizarHospedagem(Hospedagem)));
			IEnumerable<ClienteComandaDto> hospedes = val.Hospedes;
			if (hospedes != null && hospedes.Count((ClienteComandaDto x) => !HelperString.IsNullOrEmpty(x.PessoaReferencia)) == 0)
			{
				DialogoFactory.MostrarDialogoConfirma("Informe uma pessoa cadastrada para ser responsável pelo lançamento dos itens.", false, System.Windows.HorizontalAlignment.Center);
				AtualizarPainelEsquerdo(val);
