		public async Task GerarDavOs(IEnumerable<ProdutosConsumidosQuartoViewModel> itensConsumidosNoQuarto, bool navegarNaLista = false)
		{
			try
			{
				HospedagemDto hospedagemAtualizada = default(HospedagemDto);
				_ = hospedagemAtualizada;
				hospedagemAtualizada = await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService x) => x.ObterHospedagemReferencia(((EntityBaseDto)Hospedagem).Id)));
