				{
					return;
				}
				if (hospedagemAtualizada.TotalDescontoJaAplicado > 0m)
				{
					DialogoFactory.MostrarDialogoConfirma($"Desconto já aplicado através do pré-pagamento R${HelperDecimal.FormatarCampoValor(hospedagemAtualizada.TotalDescontoJaAplicado, 2, 0, false)}.", false, System.Windows.HorizontalAlignment.Center);
				}
