				if (hospedes != null && hospedes.Count((ClienteComandaDto x) => !HelperString.IsNullOrEmpty(x.PessoaDocumento)) == 0)
				{
					DialogoFactory.MostrarDialogoConfirma("Adicione uma pessoa com documento para ser responsável pelo DAV-OS.", false, System.Windows.HorizontalAlignment.Center);
					return;
				}
				ClienteComandaDto dialogoComboBox = DialogoFactory.MostrarDialogoComboBox<ClienteComandaDto>("Informe qual pessoa será responsável pelo documento:", "Pessoas", hospedagemAtualizada.Hospedes?.Where((ClienteComandaDto x) => !HelperString.IsNullOrEmpty(x.PessoaDocumento)), "PessoaNome", true);
				if (HelperObject.IsNull((object)dialogoComboBox))
