					return;
				}
				PessoaDto pessoaResponsavelDavOs = _service.Canal<IHospedagemModuleService, PessoaDto>((Func<IHospedagemModuleService, PessoaDto>)((IHospedagemModuleService service) => service.ObterPessoa(dialogoComboBox)));
