				IEnumerable<ProdutosConsumidosQuartoViewModel> itensConsumidosQuarto = itensConsumidosNoQuarto.Where((ProdutosConsumidosQuartoViewModel x) => x.ProdutosConsumidosQuarto.QuantidadeConsumida > 0m);
				if (itensConsumidosQuarto.Any())
				{
					foreach (ProdutosConsumidosQuartoViewModel consumidosQuartoDto in itensConsumidosQuarto)
					{
						IEnumerable<ProdutoServicoEmpresaDto> source = _service.Canal<IProdutoServicoModuleService, IEnumerable<ProdutoServicoEmpresaDto>>((Func<IProdutoServicoModuleService, IEnumerable<ProdutoServicoEmpresaDto>>)((IProdutoServicoModuleService service) => service.ObterProdutoServicoEmpresaPorId(new string[1] { consumidosQuartoDto.ProdutosConsumidosQuarto.ProdutoReferencia })));
