							ProdutoServicoEmpresaReferencia = consumidosQuartoDto.ProdutosConsumidosQuarto.ProdutoReferencia,
							QuantidadeInformada = 1m,
							Estoque = new EstoqueDto
							{
								Id = ((EntityBaseDto)source.FirstOrDefault().ProdutoEmpresa.Estoque).Id,
								Quantidade = consumidosQuartoDto.ProdutosConsumidosQuarto.QuantidadeConsumida
							},
							EmpresaMovimentacao = empresaMovimentacao,
							PrecoUnitarioInformado = consumidosQuartoDto.PrecoUnitario,
							PessoaMovimentacao = pessoaResponsavelDavOs,
							TipoMovimentacao = (TipoMovimentacao)2,
							CalculadoPeloSistema = true,
							DepartamentoReferencia = DadosSistema.ObterDepartamentoVenda().DepartamentoVendaReferencia
