						if (HelperObject.Is<ItemDtoNull>((object)result))
						{
							return;
						}
						result.Numero = itensDto.Count + 1;
						itensDto.Add(result);
					}
				}
				decimal num = ((DadosSistema.UtilizarPrePagoComoDescontoHospedagem && hospedagemAtualizada.TotalPrePagamento > 0m && hospedagemAtualizada.TotalPrePagamento < hospedagemAtualizada.TotalDiaria) ? hospedagemAtualizada.TotalPrePagamento : 0m);
				ItemDto servico = new ItemDto
				{
					ProdutoServicoEmpresaReferencia = ((EntityBaseDto)hospedagemAtualizada.Servico).Id,
					QuantidadeInformada = 1m,
					EmpresaMovimentacao = empresaMovimentacao,
