		public async Task TransferirQuarto()
		{
			bool quartoOcupado = HelperObject.Is<QuartoOcupadoViewModel>((object)_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().Quartos.ItemSelecionado);
			int quartoHospedagemOrigem = 0;
			if (quartoOcupado)
			{
				quartoHospedagemOrigem = Hospedagem.Quarto;
			}
			if (DialogoFactory.MostrarDialogoSimNao("Tem certeza que deseja transferir de quarto?", false, 0, System.Windows.HorizontalAlignment.Center) == MessageBoxResult.Yes)
			{
				DateTime dataInicial = (Hospedagem.IsReservadoPreReservado ? Hospedagem.DataPrevisaoCheckIn : Hospedagem.DataInicialHospedagem);
				DateTime dataFinal = (Hospedagem.IsReservadoPreReservado ? Hospedagem.DataPrevisaoCheckOut : Hospedagem.DataFinalHospedagem);
				HospedagemDto hospedagemAtualizada = await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService x) => x.ObterHospedagemReferencia(((EntityBaseDto)Hospedagem).Id)));
				IEnumerable<HospedagemDto> source = await _service.Canal<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>((Func<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>)((IHospedagemModuleService x) => x.ObterHospedagensPorData(dataInicial, dataFinal, 99, false)));
				List<int> first = _seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.SelectMany((AgrupamentoQuartoDto x) => x.QuartosVinculados).ToList();
				Lista<KeyValuePair<string, int>> val = new Lista<KeyValuePair<string, int>>();
				foreach (int item in first.Except(source.Select((HospedagemDto x) => x.Quarto)))
				{
					val.Adicionar(new KeyValuePair<string, int>($"{item} (Livre)", item));
				}
				KeyValuePair<string, int> novoQuarto = DialogoFactory.MostrarDialogoComboBox<KeyValuePair<string, int>>("Informe o novo quarto", "Quartos livres", (IEnumerable<KeyValuePair<string, int>>)val.Itens, "Key", true);
				if (novoQuarto.Value == 0)
				{
					await _seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().PreencherTodos();
					return;
				}
				Lista<HistoricoHospedagemDto> historicos = new Lista<HistoricoHospedagemDto>();
				historicos.Adicionar(Hospedagem.HistoricoHospedagem);
				historicos.Adicionar(new HistoricoHospedagemDto
				{
					DataHora = DateTime.Now,
					Usuario = $"{DadosSistema.NomeUsuario}",
					Titulo = "Transferência de quarto",
					NovaSituacaoQuarto = new SituacaoHospedagemDto
					{
						Codigo = Hospedagem.SituacaoHospedagem.Codigo,
						Descricao = Hospedagem.SituacaoHospedagem.Descricao,
						Cor = Hospedagem.SituacaoHospedagem.Cor
					},
					Observacao = $"Transferido do quarto {Hospedagem.Quarto} para o quarto {novoQuarto.Value}.",
					SituacaoAntiga = Hospedagem.SituacaoHospedagem.Descricao,
					IsCheckOut = false
				});
				List<ItemMesaContaDto> itensQuartoNovo = new List<ItemMesaContaDto>();
				if (quartoOcupado && hospedagemAtualizada.Itens.Any())
				{
					foreach (ItemMesaContaDto itemMesaContaDto in hospedagemAtualizada.Itens)
					{
						IEnumerable<ClienteComandaDto> source2 = hospedagemAtualizada.Hospedes.Where((ClienteComandaDto x) => !x.Comanda.Equals(0));
						long quartoComanda = (source2.Any() ? itemMesaContaDto.NumeroMesaConta : novoQuarto.Value);
						itensQuartoNovo.Add((await DadosSistema.GetService().Canal<IRestauranteModuleService, Task<IEnumerable<ItemMesaContaDto>>>((Func<IRestauranteModuleService, Task<IEnumerable<ItemMesaContaDto>>>)((IRestauranteModuleService service) => service.TransferirItensMesaConta((IEnumerable<ItemMesaContaDto>)(object)new ItemMesaContaDto[1] { itemMesaContaDto }, quartoComanda, false, novoQuarto.Value)))).FirstOrDefault());
					}
				}
				Hospedagem.Itens = new List<ItemMesaContaDto>();
				Hospedagem.Itens = itensQuartoNovo;
				Hospedagem.Quarto = novoQuarto.Value;
				Hospedagem.AgrupamentoReferencia = ((EntityBaseDto)_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto x) => x.QuartosVinculados.Contains(novoQuarto.Value))).Id;
				Hospedagem.Servico = hospedagemAtualizada.Servico;
				Hospedagem.MotivoViagem = hospedagemAtualizada.MotivoViagem;
				Hospedagem.MeioTransporte = hospedagemAtualizada.MeioTransporte;
				Hospedagem.HistoricoHospedagem = historicos.Itens;
				Hospedagem = await _service.Canal<IHospedagemModuleService, Task<HospedagemDto>>((Func<IHospedagemModuleService, Task<HospedagemDto>>)((IHospedagemModuleService service) => service.AtualizarHospedagem(Hospedagem)));
				_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().Quartos.Posicionar((Expression<Func<QuartoViewModel, bool>>)((QuartoViewModel x) => x.Numero.Equals(Hospedagem.Quarto)));
				if (quartoHospedagemOrigem > 0)
				{
					Lista<KeyValuePair<int, string>> val2 = new Lista<KeyValuePair<int, string>>();
					val2.Adicionar(new KeyValuePair<int, string>(1, "Livre"));
					val2.Adicionar(new KeyValuePair<int, string>(2, "Aguardando limpeza"));
					val2.Adicionar(new KeyValuePair<int, string>(3, "Aguardando manutenção"));
					switch (DialogoFactory.MostrarDialogoComboBox<KeyValuePair<int, string>>("Informe a situação desejada para o quarto anteriormente ocupado", "Situações disponíveis", (IEnumerable<KeyValuePair<int, string>>)val2.Itens, "Value", true).Key)
					{
					case 2:
						await SetarQuartoAguardandoLimpeza(quartoHospedagemOrigem);
						break;
					case 3:
						_seletorDireito.Get<PainelDireitoManutencao>().Preencher(quartoHospedagemOrigem);
						_seletorDireito.Selecionar<PainelDireitoManutencao>();
						break;
					}
				}
				AtualizarPainelEsquerdo(Hospedagem);
			}
			else
			{
				_seletorEsquerdo.Get<PainelEsquerdoListaQuartos>().PesquisarCommand.Execute(1);
			}
		}

