		public PainelEsquerdoListaQuartos(IWService service, Seletor<IPainel> seletorDireito, Seletor<IPainel> seletorEsquerdo)
		{
			//IL_00d8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00dd: Unknown result type (might be due to invalid IL or missing references)
			//IL_00e8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00f8: Expected O, but got Unknown
			//IL_0131: Unknown result type (might be due to invalid IL or missing references)
			//IL_013b: Expected O, but got Unknown
			//IL_0141: Unknown result type (might be due to invalid IL or missing references)
			//IL_014b: Expected O, but got Unknown
			//IL_01f7: Unknown result type (might be due to invalid IL or missing references)
			//IL_0201: Expected O, but got Unknown
			//IL_0223: Unknown result type (might be due to invalid IL or missing references)
			//IL_022d: Expected O, but got Unknown
			//IL_0263: Unknown result type (might be due to invalid IL or missing references)
			//IL_026d: Expected O, but got Unknown
			_service = service;
			_seletorEsquerdo = seletorEsquerdo;
			_seletorDireito = seletorDireito;
			_quartos = new Lista<QuartoViewModel>();
			AgrupamentosQuartos = new Lista<AgrupamentoQuartoDto>();
			AgrupamentosQuartos.Adicionar(service.Canal<IAgrupamentoQuartoModuleService, IEnumerable<AgrupamentoQuartoDto>>((Func<IAgrupamentoQuartoModuleService, IEnumerable<AgrupamentoQuartoDto>>)((IAgrupamentoQuartoModuleService x) => x.ObterAgrupamentosAtivos())));
			AgrupamentosQuartos.Adicionar(new AgrupamentoQuartoDto
			{
				Id = "Todos",
				Descricao = "Todos"
			});
			Quartos = new Lista<QuartoViewModel>();
			ObservableExtensions.Subscribe<QuartoViewModel>(Quartos.WhenAlterouItemSelecionado, (Action<QuartoViewModel>)delegate(QuartoViewModel itemSelecionado)
			{
				seletorDireito.Get<PainelDireitoHospedagem>().Preencher(itemSelecionado);
			});
			SituacaoHospedagem = new Lista<SituacaoQuarto>();
			SituacaoHospedagem.Adicionar((SituacaoQuarto)new CheckInAtrasado());
			SituacaoHospedagem.Adicionar((SituacaoQuarto)new CheckOutAtrasado());
			SituacaoHospedagem.Adicionar((IEnumerable<SituacaoQuarto>)SituacoesQuartos.Dados);
			SituacaoHospedagem.Remover(SituacaoHospedagem.Itens.FirstOrDefault((SituacaoQuarto x) => x.Codigo.Equals(7)));
			SituacaoHospedagem.Remover(SituacaoHospedagem.Itens.FirstOrDefault((SituacaoQuarto x) => x.Codigo.Equals(5)));
			PosicionarConfiguracaoSituacaoPadrao();
			CtrlQCommand = (ICommand)new DelegateCommand((Action)Mapa, (Func<bool>)PodeAbrirMapa, (bool?)null);
			CtrlHCommand = (ICommand)new DelegateCommand((Action)ReservasHunit, (Func<bool>)PodeVisualizarReservasHunit, (bool?)null);
			PesquisarCommand = (ICommand)new AsyncCommand((Func<Task>)Pesquisar, (Func<bool>)(() => true), false, (bool?)null);
		}

		public void PosicionarConfiguracaoSituacaoPadrao()
		{
			if (!HelperIEnumerable.IsEmpty<char>((IEnumerable<char>)DadosSistema.ConfiguracaoDto.Geral.SituacaoPadraoMapaQuartos.Valor))
			{
				SituacaoHospedagem.Posicionar((Expression<Func<SituacaoQuarto, bool>>)((SituacaoQuarto x) => x.Descricao.Equals(DadosSistema.ConfiguracaoDto.Geral.SituacaoPadraoMapaQuartos.Valor)));
			}
			else
			{
				SituacaoHospedagem.PosicionarNoUltimo();
			}
		}

		public bool PodeAbrirMapa()
		{
			return !PesquisandoQuartos;
		}

		public bool PodeVisualizarReservasHunit()
		{
			if (HelperString.IsNullOrEmpty(DadosSistema.ConfiguracaoDto.Geral.LoginHunit.Valor) && HelperString.IsNullOrEmpty(DadosSistema.ConfiguracaoDto.Geral.SenhaHunit.Valor))
			{
				return !HelperString.IsNullOrEmpty(DadosSistema.ConfiguracaoDto.Geral.CodigoHotelHunit.Valor);
			}
			return true;
		}

		public async void ReservasHunit()
		{
			await _seletorEsquerdo.Get<PainelEsquerdoReservasHunit>().AtualizarReservasHunit();
			_seletorEsquerdo.Selecionar<PainelEsquerdoReservasHunit>();
			_seletorDireito.Selecionar<PainelDireitoHunit>();
		}

		public async Task Pesquisar()
		{
			try
			{
				Pagina = 1;
				_quartoPosicionado = Quartos?.ItemSelecionado;
				await PreencherQuartosItemSelecionado(SituacaoHospedagem.ItemSelecionado.Codigo);
				if (SituacaoHospedagem.ItemSelecionado.Codigo.Equals(99) && !HelperString.IsNullOrEmpty(TextoPesquisa))
				{
					foreach (QuartoViewModel iten in Livres.Itens)
					{
						Quartos.Remover(iten);
					}
				}
				if (((EntityBaseDto)AgrupamentosQuartos.ItemSelecionado).Id.Equals("Todos"))
				{
					return;
				}
				_quartos.Limpar();
				_quartos.Adicionar((IEnumerable<QuartoViewModel>)Quartos.Itens);
				Quartos.Limpar();
				foreach (int grupo in AgrupamentosQuartos.ItemSelecionado.QuartosVinculados)
				{
					Quartos.Adicionar(_quartos.Itens.Where((QuartoViewModel x) => x.Numero.Equals(grupo)));
				}
			}
			catch (Exception)
			{
			}
			finally
			{
				TextoPesquisa = string.Empty;
				((UpdateViewBindableBase)this).RecuperarFoco();
			}
		}

		public async Task PreencherQuartosItemSelecionado(int situacaoSelecionada)
		{
			switch (situacaoSelecionada)
			{
			case 6:
				await PreencherQuartosLivres();
				break;
			case 7:
				await PreencherQuartosLivres();
				break;
			case 1:
				await PreencherQuartosPreReseservados();
				break;
			case 2:
				await PreencherQuartosReservados();
				break;
			case 3:
				await PreencherQuartosOcupados();
				break;
			case 9:
				await PreencherQuartosAguardandoLimpeza();
				break;
			case 4:
				await PreencherQuartosLimpeza();
				break;
			case 8:
				await PreencherQuartosManutencao();
				break;
			case 10:
				await PreencherQuartosAguardandoManutencao();
				break;
			case 88:
				await PreencherQuartosCheckInAtrasado();
				break;
			case 89:
				await PreencherQuartosCheckOutAtrasado();
				break;
			default:
				await PreencherTodos();
				break;
			}
		}

		public async void Mapa()
		{
			await PreencherTodos();
			SituacaoHospedagem.Posicionar((Expression<Func<SituacaoQuarto, bool>>)((SituacaoQuarto x) => x.Codigo.Equals(99)));
			_seletorEsquerdo.Get<PainelEsquerdoMapaQuartos>().ProjetarQuartos(Quartos.Itens, AgrupamentosQuartos.Itens);
			_seletorEsquerdo.Selecionar<PainelEsquerdoMapaQuartos>();
		}

		public void Habilitar<T>(Seletor<IPainel> seletorDireito)
		{
			Habilitado = HelperObject.Is<T>((object)seletorDireito.Painel);
		}

		public async Task AtualizarMapaQuartos(int situacaoQuarto)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Processando...");
				PesquisandoQuartos = true;
				PesquisaDto pesquisa = new PesquisaDto
				{
					Informacao = (InformacaoBaseDto)new TextoNumericoDto
					{
						Texto = HelperString.ToStringEmptyWhenNull(TextoPesquisa)
					},
					Pagina = Pagina
				};
				Preencher(await _service.Canal<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>((Func<IHospedagemModuleService, Task<IEnumerable<HospedagemDto>>>)((IHospedagemModuleService x) => x.ObterHospedagensAtivas(pesquisa, situacaoQuarto))));
			}
			catch (Exception ex)
			{
				HelperException.ShowLastException(ex, "", false, false);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
				PesquisandoQuartos = false;
			}
		}

		private void Preencher(IEnumerable<HospedagemDto> result)
		{
			LimparTodosQuartos();
			foreach (HospedagemDto item in result)
			{
				int numeroQuartoDto = HelperObject.ToInt((object)item.Quarto);
				string descricao = AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto x) => x.QuartosVinculados.Contains(numeroQuartoDto)).Descricao;
				switch (item.SituacaoHospedagem.Codigo)
				{
				case 1:
					PreReservado.Adicionar((QuartoViewModel)new QuartoPreReservadoViewModel(numeroQuartoDto, descricao, item));
					break;
				case 2:
					Reservado.Adicionar((QuartoViewModel)new QuartoReservadoViewModel(numeroQuartoDto, descricao, item));
					break;
				case 9:
					AguardandoLimpeza.Adicionar((QuartoViewModel)new QuartoAguardandoLimpezaViewModel(numeroQuartoDto, descricao, item));
					break;
				case 4:
					Limpeza.Adicionar((QuartoViewModel)new QuartoLimpezaViewModel(numeroQuartoDto, descricao, item));
					break;
				case 8:
					Manutencao.Adicionar((QuartoViewModel)new QuartoManutencaoViewModel(numeroQuartoDto, descricao, item));
					break;
				case 10:
					AguardandoManutencao.Adicionar((QuartoViewModel)new QuartoAguardandoManutencaoViewModel(numeroQuartoDto, descricao, item));
					break;
				default:
					Ocupado.Adicionar((QuartoViewModel)new QuartoOcupadoViewModel(numeroQuartoDto, descricao, item));
					break;
				}
			}
			List<int> first = HelperIEnumerable.ToListEmptyWhenNull<int>(Ocupado.Itens.Select((QuartoViewModel x) => x.Numero));
			List<int> second = HelperIEnumerable.ToListEmptyWhenNull<int>(AguardandoLimpeza.Itens.Select((QuartoViewModel x) => x.Numero));
			List<int> second2 = HelperIEnumerable.ToListEmptyWhenNull<int>(AguardandoManutencao.Itens.Select((QuartoViewModel x) => x.Numero));
			List<int> second3 = HelperIEnumerable.ToListEmptyWhenNull<int>(Limpeza.Itens.Select((QuartoViewModel x) => x.Numero));
			IEnumerable<int> second5 = Enumerable.Concat(second: HelperIEnumerable.ToListEmptyWhenNull<int>(Manutencao.Itens.Select((QuartoViewModel x) => x.Numero)), first: first.Concat(second).Concat(second3).Concat(second2));
			List<int> first2 = AgrupamentosQuartos.Itens.SelectMany((AgrupamentoQuartoDto x) => x.QuartosVinculados).ToList();
			Livres.Adicionar((IEnumerable<QuartoViewModel>)(from x in first2.Except(second5)
				select new QuartoLivreViewModel(x, AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto y) => y.QuartosVinculados.Contains(x)).Descricao, (HospedagemDto)new HospedagemDtoNull())));
		}

		public void LimparTodosQuartos()
		{
			Livres?.Limpar();
			PreReservado?.Limpar();
			Reservado?.Limpar();
			AguardandoLimpeza?.Limpar();
			Limpeza?.Limpar();
			Ocupado?.Limpar();
			Manutencao?.Limpar();
			AguardandoManutencao?.Limpar();
		}

		public void SetarQuartoPosicionado(string hospedagemReferencia)
		{
			_quartoPosicionado = Quartos?.Itens.FirstOrDefault((QuartoViewModel x) => x.Id.Equals(hospedagemReferencia));
			Posicionar();
		}

		public void Posicionar()
		{
			if (HelperObject.IsNotNull((object)_quartoPosicionado))
			{
				Quartos?.Posicionar((Expression<Func<QuartoViewModel, bool>>)((QuartoViewModel x) => x.Id.Equals(_quartoPosicionado.Id)));
				((UpdateViewBindableBase)this).RecuperarFoco();
			}
			else
			{
				Lista<QuartoViewModel> quartos = Quartos;
				if (quartos != null && quartos.PossuiItemSelecionado)
				{
					Quartos?.PosicionarNoPrimeiro();
					((UpdateViewBindableBase)this).RecuperarFoco();
				}
			}
			ToolTipTotais = $"Total de quartos: {Quartos.Itens.Select((QuartoViewModel x) => x.Numero).Distinct().Count()}\n" + $"Check-in atrasado: {Quartos.Itens.Count((QuartoViewModel x) => x.CheckInAtrasado)} \n" + $"Check-out atrasado: {Quartos.Itens.Count((QuartoViewModel x) => x.CheckoutAtrasado)} \n" + $"Entra hoje: {Quartos.Itens.Count((QuartoViewModel x) => x.EntraHoje)} \n" + $"Sai hoje: {Quartos.Itens.Count((QuartoViewModel x) => x.SaiHoje)}";
		}

		public async Task PreencherTodos()
		{
			await AtualizarMapaQuartos(99);
			Quartos.Limpar();
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)Livres.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)PreReservado.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)Reservado.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)Ocupado.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)AguardandoLimpeza.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)Limpeza.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)Manutencao.Itens);
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)AguardandoManutencao.Itens);
			List<QuartoViewModel> list = new List<QuartoViewModel>(Quartos.Itens.OrderBy((QuartoViewModel x) => x.Numero));
			Quartos.Limpar();
			Quartos.Adicionar((IEnumerable<QuartoViewModel>)list);
			Posicionar();
		}

