		}

		public void AtualizarHospedagem(HospedagemDto hospedagemDto)
		{
			ThreadPrincipal.Executar((Action)delegate
			{
				switch (hospedagemDto.SituacaoHospedagem.Codigo)
				{
				case 1:
					Quartos.Substituir((Expression<Func<QuartoViewModel, bool>>)((QuartoViewModel x) => ((EntityBaseDto)x.Hospedagem).Id.Equals(((EntityBaseDto)hospedagemDto).Id)), (QuartoViewModel)new QuartoPreReservadoViewModel(hospedagemDto.Quarto, AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto y) => y.QuartosVinculados.Contains(hospedagemDto.Quarto)).Descricao, hospedagemDto));
					break;
				case 2:
					Quartos.Substituir((Expression<Func<QuartoViewModel, bool>>)((QuartoViewModel x) => ((EntityBaseDto)x.Hospedagem).Id.Equals(((EntityBaseDto)hospedagemDto).Id)), (QuartoViewModel)new QuartoReservadoViewModel(hospedagemDto.Quarto, AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto y) => y.QuartosVinculados.Contains(hospedagemDto.Quarto)).Descricao, hospedagemDto));
					break;
				case 9:
					Quartos.Substituir((Expression<Func<QuartoViewModel, bool>>)((QuartoViewModel x) => ((EntityBaseDto)x.Hospedagem).Id.Equals(((EntityBaseDto)hospedagemDto).Id)), (QuartoViewModel)new QuartoAguardandoLimpezaViewModel(hospedagemDto.Quarto, AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto y) => y.QuartosVinculados.Contains(hospedagemDto.Quarto)).Descricao, hospedagemDto));
					break;
				case 4:
					Quartos.Substituir((Expression<Func<QuartoViewModel, bool>>)((QuartoViewModel x) => ((EntityBaseDto)x.Hospedagem).Id.Equals(((EntityBaseDto)hospedagemDto).Id)), (QuartoViewModel)new QuartoLimpezaViewModel(hospedagemDto.Quarto, AgrupamentosQuartos.Itens.FirstOrDefault((AgrupamentoQuartoDto y) => y.QuartosVinculados.Contains(hospedagemDto.Quarto)).Descricao, hospedagemDto));
					break;
				case 8:
