		public QuartoViewModel(int numero, string descricaoAgrupamento, HospedagemDto hospedagem)
		{
			DataInicial = hospedagem.DataPrevisaoCheckIn;
			DataFinal = hospedagem.DataPrevisaoCheckOut;
			CodigoCorQuarto = hospedagem.SituacaoHospedagem.Codigo;
			DescricaoQuarto = $"Quarto {numero}";
			ToolTip = $"{hospedagem.ClientesToText} \n" + $"Check-in: {hospedagem.DataPrevisaoCheckIn}\n" + $"Check-out: {hospedagem.DataPrevisaoCheckOut}";
			TextoCompromissoSelecionado = (hospedagem.SituacaoHospedagem.Codigo.Equals(4) ? "EM LIMPEZA" : (hospedagem.SituacaoHospedagem.Codigo.Equals(9) ? "AGUARDANDO LIMPEZA" : (hospedagem.SituacaoHospedagem.Codigo.Equals(8) ? "MANUTENÇÃO" : (hospedagem.SituacaoHospedagem.Codigo.Equals(8) ? "AGUARDANDO MANUTENÇÃO" : (HelperString.IsNullOrEmpty(hospedagem.ClientesToText) ? "HÓSPEDE NÃO INFOR." : $"{hospedagem.ClientesToText.ToUpper()}")))));
			Id = (Helper.IsEmpty((IEnumerable)((EntityBaseDto)hospedagem).Id) ? HelperObjectId.GenerateId() : ((EntityBaseDto)hospedagem).Id);
			Numero = numero;
			Hospedagem = hospedagem;
			DescricaoAgrupamento = descricaoAgrupamento;
			CheckoutAtrasado = hospedagem.SituacaoHospedagem.Codigo.Equals(3) && hospedagem.DataPrevisaoCheckOut < DateTime.Now;
			CheckInAtrasado = (hospedagem.SituacaoHospedagem.Codigo.Equals(2) || hospedagem.SituacaoHospedagem.Codigo.Equals(1)) && hospedagem.DataPrevisaoCheckIn < DateTime.Now;
			EntraHoje = (hospedagem.SituacaoHospedagem.Codigo.Equals(2) || hospedagem.SituacaoHospedagem.Codigo.Equals(1)) && hospedagem.DataPrevisaoCheckIn.Date.Equals(DateTime.Now.Date);
			SaiHoje = (hospedagem.SituacaoHospedagem.Codigo.Equals(2) || hospedagem.SituacaoHospedagem.Codigo.Equals(1)) && hospedagem.DataPrevisaoCheckOut.Date.Equals(DateTime.Now.Date);
			AllDay = false;
		}
	}
