		public HospedagemRelatorio Hospedagem { get; set; }

		public int Id { get; set; }

		public string Descricao => "Extrato da hospedagem (40 colunas)";

		public IParametros Parametros { get; set; }

		public bool ExibirNoModuloRelatorios => false;

		public ResumoHospedagem40Colunas(HospedagemDto dto)
		{
			Hospedagem = HospedagemRelatorio.Criar().ComHospedagem(dto).ComEmpresa(DadosSistema.EmpresaLogada);
			InitializeComponent();
		}

		public XtraReport Processar()
		{
			ExibirLogotipo();
			((XtraReportBase)this).DataSource = new List<HospedagemRelatorio> { Hospedagem };
			((XRControl)lblMensagemRodape).Text = "Emitido por DigiSat Tecnologia Ltda®  www.digisat.com.br";
			((XRControl)totalItens).Text = $"{HelperDecimal.FormatarCampoValor(Hospedagem.Hospedagem.Itens.Where((ItemMesaContaDto x) => !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total), 2, 0, false)}";
			((XRControl)totalServico).Text = $"{HelperDecimal.FormatarCampoValor(Hospedagem.Hospedagem.Servicos.Where((ItemDto x) => !x.Cancelado).Sum((ItemDto x) => x.Total), 2, 0, false)}";
			decimal num = Hospedagem.Hospedagem.TotalDiaria + Hospedagem.Hospedagem.Itens.Where((ItemMesaContaDto x) => !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total) + Hospedagem.Hospedagem.Servicos.Where((ItemDto x) => !x.Cancelado).Sum((ItemDto x) => x.Total) + Hospedagem.Hospedagem.ItensConsumidosNoQuarto.Where((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m).Sum((ProdutosConsumidosQuartoDto x) => HelperDecimal.ArredondarParaDuasCasasDecimais(x.PrecoUnitario * x.QuantidadeConsumida)) - Hospedagem.Hospedagem.TotalPrePagamento;
			((XRControl)sumDiariasItens).Text = $"R$ {HelperDecimal.FormatarCampoValor(num, 2, 0, false)}";
			((XRControl)grupoItens).Visible = Hospedagem.Hospedagem.Itens.Any();
			((XRControl)grupoItensConsumidosQuarto).Visible = Hospedagem.Hospedagem.ItensConsumidosNoQuarto.Any((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m);
			((XRControl)grupoServicos).Visible = Hospedagem.Hospedagem.Servicos.Any();
			return (XtraReport)(object)this;
		}

		private void ExibirLogotipo()
		{
			if (!HelperObject.IsNull((object)DadosSistema.EmpresaLogada.Imagem))
			{
				logotipoEmitente.Image = HelperImage.ToImage(HelperImage.Decompress(DadosSistema.EmpresaLogada.Imagem));
			}
			((XRControl)dadosEmitente).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)logotipoEmitente).Visible = !HelperObject.IsNull((object)logotipoEmitente.Image);
		}

		protected override void Dispose(bool disposing)
		{
			if (disposing && components != null)
			{
				components.Dispose();
			}
			((XtraReport)this).Dispose(disposing);
		}

