		public override string Descricao => "Demonstrativo consumo completo";

		public override bool ExibirNoModuloRelatorios => false;

		public HospedagemRelatorio HospedagemRelatorio { get; set; }

		public DemonstrativoConsumoTodasComandas(HospedagemDto hospedagem)
		{
			HospedagemRelatorio = HospedagemRelatorio.Criar().ComHospedagem(hospedagem).ComEmpresa(DadosSistema.EmpresaLogada);
			_hospedagemDto = hospedagem;
			InitializeComponent();
		}

		public override XtraReport Processar()
		{
			ExibirLogotipo();
			((XtraReportBase)this).DataSource = new List<HospedagemRelatorio> { HospedagemRelatorio };
			((XRControl)lblMensagemRodape).Text = "Emitido por DigiSat Tecnologia Ltda®  www.digisat.com.br";
			((XRControl)totalItens).Text = $"{HelperDecimal.FormatarCampoValor(_hospedagemDto.Itens.Where((ItemMesaContaDto x) => !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total) + _hospedagemDto.ItensConsumidosNoQuarto.Where((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m).Sum((ProdutosConsumidosQuartoDto x) => HelperDecimal.ArredondarParaDuasCasasDecimais(x.PrecoUnitario * x.QuantidadeConsumida)), 2, 0, false)}";
			((XRControl)totalServicos).Text = $"{HelperDecimal.FormatarCampoValor(_hospedagemDto.Servicos.Where((ItemDto x) => !x.Cancelado).Sum((ItemDto x) => x.Total), 2, 0, false)}";
			decimal num = _hospedagemDto.TotalDiaria + _hospedagemDto.Itens.Where((ItemMesaContaDto x) => !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total) + _hospedagemDto.ItensConsumidosNoQuarto.Where((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m).Sum((ProdutosConsumidosQuartoDto x) => HelperDecimal.ArredondarParaDuasCasasDecimais(x.PrecoUnitario * x.QuantidadeConsumida)) + _hospedagemDto.Servicos.Where((ItemDto x) => !x.Cancelado).Sum((ItemDto x) => x.Total) - _hospedagemDto.TotalPrePagamento;
			((XRControl)sumDiariasItens).Text = $"R$ {HelperDecimal.FormatarCampoValor(num, 2, 0, false)}";
			((XRControl)grupoItens).Visible = HospedagemRelatorio.Hospedagem.Itens.Any();
			((XRControl)grupoItensConsumidosQuarto).Visible = HospedagemRelatorio.Hospedagem.ItensConsumidosNoQuarto.Any((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m);
			((XRControl)grupoServicos).Visible = HospedagemRelatorio.Hospedagem.Servicos.Any();
			((XtraReport)this).ShowPrintMarginsWarning = false;
			((XtraReport)this).CreateDocument();
			return (XtraReport)(object)this;
		}

		private void ExibirLogotipo()
		{
			if (!HelperObject.IsNull((object)DadosSistema.EmpresaLogada.Imagem))
			{
				logotipoEmitente.Image = HelperImage.ToImage(HelperImage.Decompress(DadosSistema.EmpresaLogada.Imagem));
			}
			((XRControl)dadosEmitente).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)logotipoEmitente).Visible = !HelperObject.IsNull((object)logotipoEmitente.Image);
		}

		protected override void Dispose(bool disposing)
		{
			if (disposing && components != null)
			{
				components.Dispose();
			}
			((XtraReport)this).Dispose(disposing);
		}

