		public override string Descricao => "Demonstrativo consumo";

		public override bool ExibirNoModuloRelatorios => false;

		public HospedagemRelatorio HospedagemRelatorio { get; set; }

		public DemonstrativoConsumo(HospedagemDto hospedagem, PessoaDto pessoa, int comanda)
		{
			//IL_0013: Unknown result type (might be due to invalid IL or missing references)
			//IL_0018: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_0042: Expected O, but got Unknown
			HospedagemDto hospedagem2 = new HospedagemDto
			{
				Quarto = hospedagem.Quarto,
				Itens = hospedagem.Itens.Where((ItemMesaContaDto x) => x.NumeroMesaConta.Equals(comanda))
			};
			HospedagemRelatorio = HospedagemRelatorio.Criar().ComHospedagem(hospedagem2).ComEmpresa(DadosSistema.EmpresaLogada)
				.ComPessoa(pessoa);
			_hospedagemDto = hospedagem;
			_comanda = comanda;
			InitializeComponent();
		}

		public override XtraReport Processar()
		{
			ExibirLogotipo();
			((XtraReportBase)this).DataSource = new List<HospedagemRelatorio> { HospedagemRelatorio };
			((XRControl)lblMensagemRodape).Text = "Emitido por DigiSat Tecnologia Ltda®  www.digisat.com.br";
			((XRControl)totalItens).Text = $"{HelperDecimal.FormatarCampoValor(_hospedagemDto.Itens.Where((ItemMesaContaDto x) => x.NumeroMesaConta.Equals(_comanda) && !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total), 2, 0, false) + HelperDecimal.FormatarCampoValor(_hospedagemDto.ItensConsumidosNoQuarto.Where((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m).Sum((ProdutosConsumidosQuartoDto x) => HelperDecimal.ArredondarParaDuasCasasDecimais(x.PrecoUnitario * x.QuantidadeConsumida)), 2, 0, false)}";
			((XRControl)totalGeral).Text = $"{HelperDecimal.FormatarCampoValor(_hospedagemDto.Itens.Where((ItemMesaContaDto x) => x.NumeroMesaConta.Equals(_comanda) && !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total) + _hospedagemDto.ItensConsumidosNoQuarto.Where((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m).Sum((ProdutosConsumidosQuartoDto x) => HelperDecimal.ArredondarParaDuasCasasDecimais(x.PrecoUnitario * x.QuantidadeConsumida) + _hospedagemDto.Servicos.Where((ItemDto y) => !y.Cancelado).Sum((ItemDto y) => y.Total)), 2, 0, false)}";
			((XRControl)totalServico).Text = $"{HelperDecimal.FormatarCampoValor(_hospedagemDto.Servicos.Where((ItemDto x) => !x.Cancelado).Sum((ItemDto x) => x.Total), 2, 0, false)}";
			((XRControl)grupoItens).Visible = HospedagemRelatorio.Hospedagem.Itens.Any();
			((XRControl)grupoItensConsumidosQuarto).Visible = HospedagemRelatorio.Hospedagem.ItensConsumidosNoQuarto.Any((ProdutosConsumidosQuartoDto x) => x.QuantidadeConsumida > 0m);
			((XRControl)grupoServicos).Visible = HospedagemRelatorio.Hospedagem.Servicos.Any();
			((XtraReport)this).ShowPrintMarginsWarning = false;
			((XtraReport)this).CreateDocument();
			return (XtraReport)(object)this;
		}

		private void ExibirLogotipo()
		{
			if (!HelperObject.IsNull((object)DadosSistema.EmpresaLogada.Imagem))
			{
				logotipoEmitente.Image = HelperImage.ToImage(HelperImage.Decompress(DadosSistema.EmpresaLogada.Imagem));
			}
			((XRControl)dadosEmitente).Visible = HelperObject.IsNull((object)logotipoEmitente.Image);
			((XRControl)logotipoEmitente).Visible = !HelperObject.IsNull((object)logotipoEmitente.Image);
		}

		protected override void Dispose(bool disposing)
		{
			if (disposing && components != null)
			{
				components.Dispose();
			}
			((XtraReport)this).Dispose(disposing);
		}

