	public class HospedagemRelatorio
	{
		public Pessoa Empresa { get; set; }

		public HospedagemDto Hospedagem { get; set; }

		public PessoaDto Pessoa { get; set; }

		public HospedagemRelatorio(Pessoa empresa, HospedagemDto hospedagem, PessoaDto pessoa)
		{
			Empresa = empresa;
			Hospedagem = hospedagem;
			Pessoa = pessoa;
		}

		public HospedagemRelatorio()
		{
		}

		public static HospedagemRelatorio Criar()
		{
			return new HospedagemRelatorio();
		}

		public HospedagemRelatorio ComEmpresa(Pessoa empresa)
		{
			Empresa = empresa;
			return Build();
		}

		public HospedagemRelatorio ComHospedagem(HospedagemDto hospedagem)
		{
			Hospedagem = hospedagem;
			return Build();
		}

		public HospedagemRelatorio ComPessoa(PessoaDto pessoa)
		{
			Pessoa = pessoa;
			return Build();
		}

		protected HospedagemRelatorio Build()
		{
			return new HospedagemRelatorio(Empresa, Hospedagem, Pessoa);
		}
	}
